arguments.argument:
{
    xoffset=-3;
    yoffset=-6;
    refireTime = 5;

    normalSprite = WranglerS;
    recoilSprite = WranglerS;
    reloadSprite = WranglerS;
    maxAmmo = 100;
    reloadTime = 20;
    reloadBuffer = 20;
    event_inherited();

    weaponType = WTYPE_SPECIAL;
    weaponGrade = WGRADE_UNIQUE;
    ammoCount = owner.ammo[activeWeapon];

    owner.buildObject[0] = MiniSentry;
    owner.buildAmount = 80;

    sprite_index = normalSprite;

    recoilTime = refireTime;
    recoilAnimLength = sprite_get_number(recoilSprite)/2;
    recoilImageSpeed = recoilAnimLength/recoilTime;

    reloadAnimLength = sprite_get_number(reloadSprite)/2;
    reloadImageSpeed = reloadAnimLength/reloadTime;
}
